changes.before:
.mini-options { display: grid; grid-template-columns: 43px 35px; gap: 3px; padding: 2px; border: 1px solid var(--line); border-radius: 6px; background: var(--surface-soft); }
.mini-options--position { grid-template-columns: 48px 48px; }
.mini-options--conversation-precision { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.mini-option { height: 23px; font-size: 11px; }

changes.after:
/* 按译文的实际宽度分配按钮，避免 Before content、Second 和日文正文位置被截断。 */
.mini-options { display: grid; grid-template-columns: repeat(2, minmax(max-content, 1fr)); gap: 3px; padding: 2px; border: 1px solid var(--line); border-radius: 6px; background: var(--surface-soft); }
.mini-options--conversation-precision { grid-template-columns: repeat(3, minmax(max-content, 1fr)); }
.mini-option { height: 23px; padding: 0 8px; font-size: 11px; white-space: nowrap; }

changes.before:
.live-preview__label { margin-bottom: 8px; color: #85878d; font-size: 13px; font-weight: 500; }
.preview-line { min-width: 0; min-height: 27px; display: grid; grid-template-columns: 60px minmax(0, 1fr); gap: 8px; align-items: center; color: #5c5e65; font-size: 11px; }
.preview-line > span:last-child { min-width: 0; overflow: hidden; font-variant-numeric: tabular-nums; text-overflow: ellipsis; white-space: nowrap; }
.preview-key { color: #9a9ca1; white-space: nowrap; }

changes.after:
/* 两行共享按译文测量的标签列；display: contents 只展平无语义的行包装，不依赖 subgrid。
   时间值空间不足时显示完整内容，不用省略号掩盖日期。 */
.live-preview { display: grid; grid-template-columns: max-content minmax(0, 1fr); column-gap: 12px; align-items: baseline; }
.live-preview__label { grid-column: 1 / -1; margin-bottom: 8px; color: #85878d; font-size: 13px; font-weight: 500; }
.preview-line { display: contents; color: #5c5e65; font-size: 11px; }
.preview-line > span { min-width: 0; padding: 6px 0; }
.preview-line > span:last-child { font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.preview-key { color: #9a9ca1; white-space: nowrap; }

/* 6.5em 的统一标签列可容纳 Orientation / 文字サイズ；按钮按文字最小宽度分配。 */
.export-choice-row { min-height: 33px; display: grid; grid-template-columns: 6.5em minmax(0, 1fr); align-items: center; gap: 8px; color: #777980; font-size: 11px; }
.export-mini-segment { min-width: 0; height: 27px; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(max-content, 1fr); gap: 2px; padding: 2px; border: 1px solid var(--border); border-radius: 6px; background: var(--surface-subtle); }
